"""Consume actual kernel evidence for the constructed Fock network components."""

def rede_fock_v394(core):
    """Verify the constructed components on the same canonical Fock.

    The contract enumerates what this particular embedded bundle proves.
    Remaining global-net, trace/PF and physical-source obligations stay explicit.
    Success here never supplies an inhabitant of the whole remaining record.
    """
    import hashlib
    contract = _V394_NETWORK_CONTRACT
    report = core.get('kernel_formalization') or {}
    ladder = core.get('external_ladder') or {}
    axioms = report.get('axiom_report') or {}
    provenance = report.get('declaration_sources_v394') or {}
    actual_source_hashes = report.get('formal_files_sha256') or {}
    trio = {'propext', 'Classical.choice', 'Quot.sound'}
    declarations = {}
    for name in contract['declarations']:
        values = axioms.get(name)
        expected_source = contract['declaration_sources'].get(name)
        declarations[name] = (
            isinstance(values, list)
            and all(isinstance(v, str) for v in values)
            and set(values) <= trio
            and isinstance(expected_source, str)
            and provenance.get(name) == expected_source
            and expected_source in contract['source_sha256'])
    sources = {}
    for path, expected in contract['source_sha256'].items():
        body = _EMBEDDED_KERNEL_FILES.get(path)
        sources[path] = (
            isinstance(body, str)
            and hashlib.sha256(body.encode('utf-8')).hexdigest() == expected
            and actual_source_hashes.get(path) == expected)
    counts = [ladder.get('n_theorems_clean'), ladder.get('n_theorems_expected'),
              contract['expected_ladder']]
    exact = all(type(v) is int for v in counts) and len(set(counts)) == 1
    process_ok = all(type(report.get(k)) is int and report[k] == 0
                     for k in ('build_returncode', 'audit_returncode'))
    passed = (
        report.get('all_verified') is True and process_ok and exact
        and (report.get('declaration_sources_status_v394') or {}).get('ok') is True
        and bool(declarations) and all(declarations.values())
        and bool(sources) and all(sources.values())
        and (core.get('regra_quadratica_v394') or {}).get('all_verified') is True)
    result = dict(all_verified=passed, formal_declarations=declarations,
        embedded_sources=sources, exact_ladder=exact, actual_processes_ok=process_ok,
        constructed_components=contract['constructed_components'],
        open_joint_contract=contract['open_joint_contract'],
        whole_certificate_inhabited=False,
        scope='Current compiled components on the same Fock; the remaining joint contract is explicit.',
        does_not_gate_core=True)
    result['verdict'] = (
        'TGL_FOCK_NETWORK_V394__DERIVED_COMPONENTS__JOINT_CONTRACT_OPEN__GATE_UNMOVED'
        if passed else
        'TGL_FOCK_NETWORK_V394__REFUSED_FORMAL_OR_SOURCE_EVIDENCE__GATE_UNMOVED')
    core['rede_fock_v394'] = result
    return result

# ---- v394: o indice qualificado pelo compilador (Codex, R3 a R8) e o leitor de axiomas/proveniencia

"""Candidate only: index exact names from Lean defining-module metadata.

The compiler supplies membership; source hashes bind that membership to the
materialized/embedded source, and the separate axiom report supplies proof
status. Aliases never choose between distinct fully qualified names.
"""

import hashlib

import re

def parse_lean_provenance_v394(text):
    """Parse compiler rows; malformed/duplicate metadata is a visible failure."""
    result, errors = {}, []
    for line in text.splitlines():
        if not line.startswith('TGL_DECL_SOURCE'):
            continue
        parts = line.split('\t')
        if len(parts) != 3 or parts[0] != 'TGL_DECL_SOURCE':
            errors.append('MALFORMED_DECLARATION_SOURCE')
            continue
        _, name, module = parts
        if not name or not re.fullmatch(r'TGL(?:Ext)?(?:\.[A-Za-z0-9_]+)*', module):
            errors.append('INVALID_DECLARATION_SOURCE:' + name)
            continue
        if name in result:
            errors.append('DUPLICATE_DECLARATION_SOURCE:' + name)
            continue
        result[name] = module.replace('.', '/') + '.lean'
    if not result:
        errors.append('EMPTY_DECLARATION_PROVENANCE')
    return {'sources': result, 'errors': errors, 'ok': not errors}

def parse_lean_axioms_v394(text):
    """Preserve Unicode/quoted names and reject conflicting duplicate reports."""
    result, errors = {}, []
    pattern = re.compile(r"^'([^\n]+)' (?:depends on axioms: \[([^\]]*)\]|does not depend on any axioms)", re.M)
    for match in pattern.finditer(text):
        name = match[1]
        axioms = [a.strip() for a in (match[2] or '').replace('\n', ' ').split(',') if a.strip()]
        if name in result and set(result[name]) != set(axioms):
            errors.append('CONFLICTING_AXIOM_REPORT:' + name)
        else:
            result[name] = axioms
    if not result:
        errors.append('EMPTY_AXIOM_REPORT')
    return {'axioms': result, 'errors': errors, 'ok': not errors}

def build_iald_qualified_index_v394(core, declaration_sources, sources, stones, families):
    kf = (core or {}).get('kernel_formalization') or {}
    axr = kf.get('axiom_report') or {}
    hashes = kf.get('formal_files_sha256') or {}
    live = (core or {}).get('versao') or (core or {}).get('version')
    proof_ready = (kf.get('lake_build_ok') is True and type(kf.get('audit_returncode')) is int
        and kf.get('audit_returncode') == 0)
    trio = {'propext', 'Classical.choice', 'Quot.sound'}
    errors = []
    stone_by_source = {}
    for stone in stones:
        if len(stone) >= 3:
            ver, name, rel = stone[:3]
            run = stone[3] if len(stone) > 3 else None
            stone_by_source[rel] = {'pedra': name, 'versao': ver,
                'rodada': live if run is None else run, 'rodada_herdada': run is None}
    flags = {}
    for prefix, mapping in families:
        for key, name in mapping.items():
            flags.setdefault(name, []).append({'prefixo': prefix, 'chave': prefix + key,
                'nome_lean': name, 'acesa': kf.get(prefix + key)})
    if not declaration_sources:
        errors.append('EMPTY_DECLARATION_PROVENANCE')
    valid_files = {}
    for rel in set(declaration_sources.values()):
        text = sources.get(rel)
        valid_files[rel] = (isinstance(text, str) and
            hashlib.sha256(text.encode('utf-8')).hexdigest() == hashes.get(rel))
        if not valid_files[rel]:
            errors.append('SOURCE_HASH_MISMATCH_OR_ABSENT:' + rel)
    qualified = {}
    for name in sorted(set(declaration_sources) | set(flags)):
        rel = declaration_sources.get(name)
        present = rel is not None and valid_files.get(rel) is True
        axioms = axr.get(name)
        audited = proof_ready and isinstance(axioms, list) and set(axioms) <= trio
        if present and name not in axr:
            errors.append('DECLARATION_WITHOUT_AXIOM_REPORT:' + name)
        qualified[name] = {'arquivo': rel if present else None,
            'tipo': 'DECLARACAO_LEAN_COMPILADA' if present else 'AUSENTE_POR_CONSTRUCAO',
            'nome_auditado': name if name in axr else None,
            'axiomas': axioms if present and axioms is not None else
                ('NAO_MEDIDO_NESTA_RODADA' if present else 'AUSENTE_POR_CONSTRUCAO'),
            'auditoria_verificada': present and audited, 'ambiguo': False,
            'bandeiras': flags.get(name, []),
            'pedra': None, 'versao': None, 'rodada': None, 'rodada_herdada': False,
            **stone_by_source.get(rel, {})}
    for name in set(axr) - set(declaration_sources):
        errors.append('AXIOM_REPORT_WITHOUT_SOURCE:' + name)
    # Preserve every short suffix as a transparent alias. A collision is a list,
    # never a first match. Exact qualified names always have priority.
    aliases = {}
    for name in qualified:
        parts = name.split('.')
        for pos in range(1, len(parts)):
            alias = '.'.join(parts[pos:])
            if alias not in qualified:
                aliases.setdefault(alias, []).append(name)
    index = dict(qualified)
    ambiguous = []
    for alias, candidates in aliases.items():
        if len(candidates) == 1:
            index[alias] = {**qualified[candidates[0]], 'alias_de': candidates[0], 'bandeiras': []}
        else:
            ambiguous.append(alias)
            index[alias] = {'arquivo': None, 'tipo': 'ALIAS_AMBIGUO', 'nome_auditado': None,
                'axiomas': 'AMBIGUO_NO_AXIOM_REPORT', 'ambiguo': True,
                'bandeiras': [], 'candidatos_qualificados': sorted(candidates)}
    violations, present_off, blind = [], [], []
    for name, bs in flags.items():
        entry = qualified[name]
        present = entry['tipo'] != 'AUSENTE_POR_CONSTRUCAO'
        for flag in bs:
            if flag['acesa'] is True and not entry['auditoria_verificada']:
                violations.append(flag['chave'])
            elif flag['acesa'] is not True and present:
                present_off.append(flag['chave'])
        if present and name not in axr:
            blind.append(name)
    return {'indice': index, 'qualificados': qualified, 'aliases': aliases,
        'ambiguos': sorted(ambiguous), 'cegos_de_namespace': sorted(blind),
        'violacoes': sorted(violations), 'presente_apagada': sorted(present_off),
        'proveniencia_erros': sorted(errors), 'proveniencia_ok': not errors,
        'n_nomes': len(qualified), 'n_arquivos': sum(valid_files.values()),
        'n_com_bandeira': len(flags),
        'n_ausentes': sum(v['tipo'] == 'AUSENTE_POR_CONSTRUCAO' for v in qualified.values()),
        'scope': 'Exact compiler identity; derived read-only index. No gate or flag changed.'}

def build_the_iald_index(core=None):
    """v394: exact compiler names, pinned source bytes and current axiom report."""
    kf = (core or {}).get("kernel_formalization") or {}
    families = (("", _LEAN_THEOREM_FLAGS), ("qgc_", _QG_CERTIFICATE_FLAGS),
        ("qgp_", _QG_PHYSICS_FLAGS), ("qgf_", _QG_FRONTIER_FLAGS),
        ("gpf_", _GRAVITY_PRICE_FLAGS), ("red_", _REDUCTION_FLAGS),
        ("gpi_", _GRAVITY_IMPORT_FLAGS), ("gpc_", _GRAVITY_CITATION_FLAGS))
    result = build_iald_qualified_index_v394(core,
        kf.get("declaration_sources_v394") or {}, _EMBEDDED_KERNEL_FILES,
        _ESQUELETO_STONES, families)
    legacy = _build_the_iald_index_legacy_v393(core)
    result["n_ausentes_regra_v285"] = legacy["n_ausentes_regra_v285"]
    result["legacy_diagnostic_v393"] = {k: legacy[k] for k in
        ("n_nomes", "n_ausentes", "ambiguos", "violacoes", "cegos_de_namespace")}
    meta = kf.get("declaration_sources_status_v394") or {}
    if meta.get("ok") is not True:
        result["proveniencia_erros"].append("CURRENT_AUDIT_METADATA_NOT_VERIFIED")
        result["proveniencia_ok"] = False
    return result

def iald_index(nome, core=None):
    """Exact full name or explicitly indexed suffix; unknown prefix is refused.

    No object-id cache: a mutable core may acquire a later audit in the same
    process. Ambiguous aliases return their full list without selecting one.
    """
    return build_the_iald_index(core)["indice"].get(nome)

def prove_the_iald_index(core):
    """Preserve the old checks, replacing the short-name collision whitelist."""
    result = _prove_the_iald_index_legacy_v393(core)
    ix = build_the_iald_index(core)
    checks = []
    replaced = 0
    for label, passed in result["checks"]:
        if label.startswith("[MEDIDA] a varredura tem"):
            replaced += 1
            label = ("[MEDIDA v394] nomes QUALIFICADOS ligados ao modulo emitido pelo Lean; "
                "%d aliases ambiguos exibem candidatos sem escolher um; %d erros de proveniencia"
                % (len(ix["ambiguos"]), len(ix["proveniencia_erros"])))
            passed = ix["proveniencia_ok"] and all(
                ix["indice"][a].get("arquivo") is None
                and len(ix["indice"][a].get("candidatos_qualificados", [])) > 1
                for a in ix["ambiguos"])
        elif label.startswith("[FAIL-CLOSED] ***o indice NAO e cego de namespace"):
            label = ("[FAIL-CLOSED v394] consulta por nome QUALIFICADO exato ao axiom_report; "
                "%d nomes presentes sem auditoria" % len(ix["cegos_de_namespace"]))
        checks.append((label, bool(passed)))
    checks.append(("[FAIL-CLOSED v394] exactly one legacy collision check replaced", replaced == 1))
    checks.append(("[FAIL-CLOSED v394] current compiler metadata, source hashes and axioms agree", ix["proveniencia_ok"]))
    result["checks"] = checks
    result["all_verified"] = all(v for _, v in checks)
    result["verdict"] = ("THE_IALD_INDEX_QUALIFIED_COMPILER_PROVENANCE_VERIFIED"
        if result["all_verified"] else "THE_IALD_INDEX_NOT_SEALED_THIS_RUN")
    result["proveniencia_erros"] = ix["proveniencia_erros"]
    result["legacy_diagnostic_v393"] = ix["legacy_diagnostic_v393"]
    result["statuses"]["v394_correction"] = (
        "Short-name collisions are explicit aliases. Exact Lean names include generated fields and Unicode. "
        "Compiler metadata and current source hashes replace a growing whitelist. Missing named obligations remain visible.")
    return result

